  q("Tác dụng phụ của thuốc chống trầm cảm là gì?", "Tác dụng phụ thuốc chống trầm cảm: buồn nôn, thay đổi cân nặng, rối loạn tình dục, buồn ngủ, khô miệng.", "thuoc"),
  q("Dấu hiệu đột quỵ là gì?", "Đột quỵ (BE FAST): Mất thăng Bằng, mờ mắt, Mặt méo xệ, Tay yếu liệt, nói khó ngọng, gọi 115 NGAY.", "cap_cuu"),
  q("Xử lý sốc phản vệ như thế nào?", "Sốc phản vệ: gọi 115, tiêm epinephrine, nằm với chân giơ cao, phản ứng thứ hai có thể xảy ra vài giờ sau.", "cap_cuu"),
  q("Xử lý sốc nhiệt như thế nào?", "Sốc nhiệt: gọi 115, đưa vào nơi mát, làm mát nhanh bằng nước lạnh, KHÔNG cho uống nước. Nguy hiểm tính mạng.", "cap_cuu"),
  q("Xử lý co giật như thế nào?", "Co giật: bảo vệ khỏi chấn thương, không giữ chặt, đặt nằm nghiêng, tính thời gian. Gọi 115 nếu >5 phút.", "cap_cuu"),
  q("Xử lý nhồi máu cơ tim như thế nào?", "Nhồi máu cơ tim: gọi 115, nhai aspirin nếu không dị ứng, ngồi/nằm xuống, chờ cấp cứu. Từng phút đều quan trọng.", "cap_cuu"),
  q("Xử lý chảy máu nặng như thế nào?", "Cầm máu: ấn trực tiếp lên vết thương, nâng cao chi, không rút dị vật ra, gọi 115 nếu nghiêm trọng.", "cap_cuu"),
  q("Xử lý hóc dị vật như thế nào?", "Hóc dị vật: vỗ lưng, thủ thuật Heimlich (ấn bụng), lặp lại, gọi 115 nếu không lấy được.", "cap_cuu"),
  q("Xử lý bỏng như thế nào?", "Bỏng: làm mát 10-20 phút, không dùng đá/bơ, băng bằng vải sạch, đến cơ sở y tế nếu bỏng nặng.", "cap_cuu"),
  q("Xử lý đuối nước như thế nào?", "Đuối nước: đưa nạn nhân ra khỏi nước, gọi 115, CPR nếu không thở, giữ ấm đến khi có người hỗ trợ.", "cap_cuu"),
  q("Xử lý ngộ độc như thế nào?", "Ngộ độc: gọi trung tâm chống độc, không gây nôn trừ khi được hướng dẫn, giữ lại vỏ hộp/chai.", "cap_cuu"),
  q("Phòng ngừa bệnh tim như thế nào?", "Phòng ngừa bệnh tim: không hút thuốc, ăn lành mạnh, tập 150 phút/tuần, cân nặng hợp lý, hạn chế rượu bia.", "phong_ngua"),
  q("Phòng ngừa tiểu đường như thế nào?", "Phòng ngừa tiểu đường: cân nặng hợp lý, tập thể dục, ăn ngũ cốc nguyên hạt/chất xơ, hạn chế đường, không hút thuốc.", "phong_ngua"),
  q("Phòng ngừa ung thư như thế nào?", "Phòng ngừa ung thư: không hút thuốc, hạn chế rượu bia, ăn rau củ/trái cây, tập thể dục, bảo vệ da, sàng lọc định kỳ.", "phong_ngua"),
  q("Phòng ngừa đột quỵ như thế nào?", "Phòng ngừa đột quỵ: kiểm soát huyết áp, không hút thuốc, điều trị rung nhĩ, tập thể dục, ăn lành mạnh.", "phong_ngua"),
  q("Phòng ngừa cúm như thế nào?", "Phòng ngừa cúm: tiêm vaccine hàng năm, rửa tay, tránh người bệnh, không sờ tay lên mặt, lối sống lành mạnh.", "phong_ngua"),
  q("Phòng ngừa viêm phổi như thế nào?", "Phòng ngừa viêm phổi: tiêm vaccine cúm, vaccine phế cầu, vệ sinh tốt, bỏ thuốc lá, kiểm soát bệnh mãn tính.", "phong_ngua"),
  q("Phòng ngừa loãng xương như thế nào?", "Phòng ngừa loãng xương: đủ canxi/vitamin D, tập thể dục chịu tải, không hút thuốc, hạn chế rượu bia.", "phong_ngua"),
  q("Phòng ngừa trầm cảm như thế nào?", "Phòng ngừa trầm cảm: tập thể dục, ngủ đủ giấc, duy trì quan hệ xã hội, kiểm soát căng thẳng, tìm trợ giúp sớm.", "phong_ngua"),
  q("Phòng ngừa Alzheimer như thế nào?", "Phòng ngừa Alzheimer: tập thể dục, ăn lành mạnh, giao tiếp xã hội, rèn luyện trí não, kiểm soát nguy cơ tim mạch.", "phong_ngua"),
  q("Phòng ngừa nhiễm trùng như thế nào?", "Phòng ngừa nhiễm trùng: rửa tay, tiêm vaccine, ăn uống an toàn, quan hệ an toàn, không dùng chung vật dụng.", "phong_ngua"),
  q("Chế độ ăn lành mạnh là gì?", "Chế độ ăn lành mạnh: rau củ, trái cây, ngũ cốc nguyên hạt, protein nạc, chất béo tốt. Hạn chế thực phẩm chế biến sẵn, đường, muối.", "kien_thuc_chung"),
